<?php
$x = trim(fgets(STDIN));
$x = (int)$x; // PHP int is 64-bit on most systems, safe for 1e18

function mod360($n) {
    $m = $n % 360;
    if ($m < 0) $m += 360;
    return $m;
}

$base = mod360(-$x);

$bestK = 0;
$bestDev = PHP_INT_MAX;

for ($k = 0; $k < 4; $k++) {
    $total = mod360($base + 90 * $k);
    $dev = min($total, 360 - $total);
    if ($dev < $bestDev) {
        $bestDev = $dev;
        $bestK = $k;
    }
}

echo $bestK . "\n";
?>
